CREATE OR REPLACE FUNCTION public.accept_wave(_wave_id uuid,_trader uuid) RETURNS public.wave_orders LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w waves; o wave_orders; line jsonb; s stock; total numeric:=0; qty integer; BEGIN IF NOT EXISTS(SELECT 1 FROM user_roles WHERE user_id=_trader AND role='trader') THEN RAISE EXCEPTION 'trader-profile-required'; END IF; IF NOT EXISTS(SELECT 1 FROM profiles WHERE id=_trader AND online AND lat IS NOT NULL AND lng IS NOT NULL) THEN RAISE EXCEPTION 'trader-offline'; END IF; SELECT * INTO w FROM waves WHERE id=_wave_id FOR UPDATE; IF w.id IS NULL OR w.buyer_id=_trader THEN RAISE EXCEPTION 'invalid-wave'; END IF; SELECT * INTO o FROM wave_orders WHERE wave_id=w.id; IF o.id IS NOT NULL THEN IF o.trader_id=_trader AND o.cancelled_at IS NULL THEN RETURN o; END IF; RAISE EXCEPTION 'wave-already-accepted'; END IF; IF w.status<>'created' OR w.expires_at<=now() THEN RAISE EXCEPTION 'wave-expired'; END IF; IF jsonb_array_length(w.items)=0 THEN RAISE EXCEPTION 'itemized-order-required'; END IF; FOR line IN SELECT * FROM jsonb_array_elements(w.items) LOOP qty:=(line->>'qty')::integer; SELECT * INTO s FROM stock WHERE trader_id=_trader AND item_id=line->>'id' AND available ORDER BY id LIMIT 1 FOR UPDATE; IF s.id IS NULL OR qty<1 OR s.quantity<qty THEN RAISE EXCEPTION 'insufficient-stock'; END IF; total:=total+s.price*qty; UPDATE stock SET quantity=quantity-qty WHERE id=s.id; END LOOP; UPDATE waves SET status='accepted',trader_id=_trader WHERE id=w.id; INSERT INTO wave_orders(wave_id,buyer_id,trader_id,items,amount,note,status) VALUES(w.id,w.buyer_id,_trader,w.items,round(total,2),w.note,'accepted') RETURNING * INTO o; RETURN o; END $$;
CREATE OR REPLACE FUNCTION public.guard_new_momo_payment() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM wave_orders WHERE id=NEW.order_id AND cancelled_at IS NULL AND payment_method='mtn-momo' AND status<>'completed') THEN RAISE EXCEPTION 'order-not-payable'; END IF; RETURN NEW; END $$; CREATE TRIGGER guard_new_momo_payment BEFORE INSERT ON public.payments FOR EACH ROW EXECUTE FUNCTION public.guard_new_momo_payment();
CREATE OR REPLACE FUNCTION public.expire_waves() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN UPDATE waves SET status='expired' WHERE status='created' AND expires_at<=now(); GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
